void add_queen(int *board, int n, int  counter, int *result)
{
    if (counter >= n) {
        return;
    }
    for (int i = 0; i < n; ++i) {
        if (free_place(board, n, counter, i)) {
            board[counter] = i;
            count_edit(counter, n, result);
            add_queen(board, n, counter + 1, result);
